function resetFilters(){['year','month','port','hs','tax','country','procedure','scheme','band','cohort','policy'].forEach(k=>{state[k]=k==='year'?'2026':'all';$('#'+k).value=state[k];});state.search='';state.page=0;updateFilterCount();log('Reset filters');render();}
