function route(){const id=location.hash.slice(1)==='policy'?'scenarios':location.hash.slice(1);if(modules.some(m=>m[0]===id)){state.tab=id;state.search='';state.page=0;log('Opened '+modules.find(m=>m[0]===id)[2]);render();}}
window.addEventListener('hashchange',route);$('#reset').onclick=resetFilters;$('#more-filters').onclick=()=>{const p=$('#advanced');p.hidden=!p.hidden;$('#more-filters').setAttribute('aria-expanded',String(!p.hidden));};$('#close-modal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close();};$('#brief').onclick=()=>state.tab==='scenarios'?showPolicyCase():brief();
let liveTimer;$('#live').onclick=()=>{state.live=!state.live;$('#live').setAttribute('aria-pressed',state.live);$('#live').textContent=state.live?'Ⅱ Pause simulation':'▷ Simulate live';clearInterval(liveTimer);if(state.live){toast('Simulating one October 2026 record every 8 seconds.');liveTimer=setInterval(()=>{rows=D.append();log('Simulated declaration received');$('#refresh-time').textContent='Simulated update '+new Date().toLocaleTimeString('en-GB')+' · cut-off Oct 2026';render();},8000);}log(state.live?'Started simulated stream':'Paused simulated stream');};
$('#content').addEventListener('click',e=>{const card=e.target.closest('[data-kpi]');if(card)showKpi(card.dataset.kpi);const charge=e.target.closest('[data-charge]');if(charge)showCharge(charge.dataset.charge);});
$('#methodology').onclick=()=>{location.hash='guide';};
log('Loaded decision-focused Customs demo v3');route();render();
function showPolicyCase(){
 if(document.querySelector('.policy-inputs [aria-invalid="true"]'))return toast('Correct the highlighted assumption before reviewing the policy case.');
 const p=projection();if(!p)return modal('Policy case unavailable','<p>At least 24 populated historical months are required. Broaden the filters to create a future outlook.</p>');
 const t=p.totals,s=state.scenario,labels=p.output.map(x=>x.key.slice(2)),start=new Date(p.end+'-01T00:00:00Z');start.setUTCMonth(start.getUTCMonth()+1+s.startOffset);
 const assumptions=[['Import VAT',s.vatRate+'% (baseline 7.5%)'],['Import duty',s.delta+' percentage-point change'],['Eligible import excise',s.exciseRate+'% · beverage/tobacco demo'],['Concessions retained',s.relief+'% of existing relief'],['Affected products',s.targetChapter==='all'?'All filtered imports':'HS chapter '+s.targetChapter],['Collection-charge profile',s.chargeProfile==='ciss-demo'?'1% CISS; 4% FOB off':'4% FOB hypothetical; CISS off'],['Import behaviour',s.mode==='mechanical'?'Held fixed': 'Assumed elasticity '+s.elasticity+'; sensitivity ±0.3'],['Implementation',start.toISOString().slice(0,7)+' · '+(s.rollout===1?'immediate coverage':s.rollout+'-month rollout')],['Projection period',p.output[0].key+' to '+p.output.at(-1).key],['Baseline method','Same month’s prior-year basket; no growth uplift'],['Cash collection','Historical component settlement ratios; 94% fallback for zero baseline bills'],['Other receipts','Eligible domestic accounting receipts held unchanged']];
 const tiles=[['Collections with proposal',money(t.policy),'Unchanged policy '+money(t.baseline)],['Net fiscal change',signed(p.change),pct(p.change,t.baseline)+' versus unchanged policy'],['Cash forgone',money(p.forgone),'Reduction versus unchanged policy only'],['Concession cost',money(t.concessions),'Change '+signed(t.concessions-t.baselineConcessions)]];
 const body=`<article class="policy-case"><header class="case-hero"><span class="case-eyebrow">CONDITIONAL FUTURE OUTLOOK · SYNTHETIC DATA</span><h2>What could the next ${state.horizon} months look like?</h2><p>Under the conditions below, collections ${Math.abs(p.change)<.01?'remain unchanged':p.change>0?'increase':'decrease'} by <strong>${money(Math.abs(p.change))}</strong> against unchanged policy.</p><span>${p.output[0].key} — ${p.output.at(-1).key} · source cutoff ${p.end}</span></header><div class="case-metrics">${tiles.map(([label,value,note])=>`<div><span>${label}</span><strong>${value}</strong><small>${note}</small></div>`).join('')}</div><section class="case-section"><h3>01 / The future revenue path</h3><p>Compare the proposal with the same future under unchanged policy. The gap is the modelled fiscal effect.</p>${chart(labels,[{name:'Unchanged policy',values:p.output.map(x=>x.baseline),color:'#92a6aa'},{name:'Proposed policy',values:p.output.map(x=>x.policy),color:'#087f73'}],{band:s.mode==='behavioural'?{low:p.output.map(x=>x.low),high:p.output.map(x=>x.high)}:null,bandLabel:'Elasticity sensitivity ±0.3; not a confidence interval'})}</section><div class="case-columns"><section class="case-section"><h3>02 / Monthly gain or shortfall</h3>${chart(labels,[{name:'Additional / lower cash',values:p.output.map(x=>x.policy-x.baseline),color:'#087f73'}])}<p>The zero line means no difference from unchanged policy. Delayed rollout affects only months covered.</p></section><section class="case-section"><h3>03 / The trade and concession implications</h3>${simpleTable(['Measure','Unchanged policy','Proposal'],[['Import CIF',money(t.baselineValue),money(t.value)],['Import weight',num(t.baselineWeight/1e6,2)+'m kg',num(t.weight/1e6,2)+'m kg'],['Bills raised',money(t.baselineBills),money(t.bills)],['Concessions',money(t.baselineConcessions),money(t.concessions)]])}<p>Concession cost is separate from cash forgone. A VAT increase can raise both collections and the value of retained percentage relief.</p></section></div><section class="case-section"><h3>04 / Conditions behind this outlook</h3><div class="case-assumptions">${assumptions.map(([a,b])=>`<div><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}</div><p><b>Scope:</b> ${Object.entries(state).filter(([k])=>['year','month','port','hs','tax','country','procedure','scheme','band','cohort','policy'].includes(k)).map(([k,v])=>esc(k)+': '+esc(v)).join(' · ')}</p></section><section class="case-section case-reading"><h3>05 / How to use this case</h3><p>${sensitivePolicyText()} Validate affected product eligibility and settlement capacity before treating projected gains as budget resources.</p><p>This is a conditional illustration, not a prediction of Nigeria’s actual receipts. It excludes consumer prices, domestic VAT credits, jobs, GDP and welfare. Tax rules and behavioural assumptions require validation.</p>${s.startOffset>=state.horizon?'<p><b>The policy starts after this projection horizon, so the displayed period has no policy effect.</b></p>':''}</section><footer class="case-actions"><button id="case-download" class="primary">Download policy brief</button><button id="case-return">Return to assumptions</button><span>Adjust the conditions to explore a different future.</span></footer></article>`;
 modal('Policy case · future outlook',body);$('#modal').classList.add('policy-case-modal');const reviewedBrief=policyBriefText();$('#case-download').onclick=()=>download('customs-policy-brief.txt',reviewedBrief);$('#case-return').onclick=()=>$('#modal').close();log('Reviewed future policy case');
}
